package master

import (
	"net"
	"net/http"
	"regexp"
	"strings"
	"text/template"
)

// The install script is fetched over TLS pinned with curl --pinnedpubkey, so
// the checksums it embeds can be trusted to verify the downloaded binary.
var installTpl = template.Must(template.New("install").Parse(`#!/bin/sh
# coremon agent installer - generated by the master at {{.URL}}
set -eu

MASTER='{{.URL}}'
PIN='{{.Pin}}'
NEXT='{{.Next}}'
SHA_AMD64='{{.SHAAmd64}}'
SHA_ARM64='{{.SHAArm64}}'
TOKEN=""

die() { echo "coremon: $*" >&2; exit 1; }

while [ $# -gt 0 ]; do
  case "$1" in
    --token) TOKEN="${2:-}"; shift 2 ;;
    *) die "unknown argument: $1" ;;
  esac
done

[ "$(id -u)" = "0" ] || die "must run as root"
command -v systemctl >/dev/null 2>&1 || die "systemd is required"
command -v curl >/dev/null 2>&1 || die "curl is required (apt-get install -y curl)"
command -v sha256sum >/dev/null 2>&1 || die "sha256sum is required"

ENROLLED=0
[ -f /var/lib/coremon/identity.json ] && ENROLLED=1
case "$TOKEN" in ""|*[!a-f0-9]*) [ "$ENROLLED" = 1 ] || die "a valid --token is required"; TOKEN="" ;; esac

case "$(uname -m)" in
  x86_64|amd64) ARCH=amd64; SHA="$SHA_AMD64" ;;
  aarch64|arm64) ARCH=arm64; SHA="$SHA_ARM64" ;;
  *) die "unsupported architecture: $(uname -m)" ;;
esac
[ -n "$SHA" ] || die "the master has no agent build for linux-$ARCH"

TMP="$(mktemp)"
trap 'rm -f "$TMP"' EXIT
echo "coremon: downloading agent (linux-$ARCH)"
curl -fsSL -k --pinnedpubkey "sha256//$PIN" -o "$TMP" "$MASTER/dl/agent/linux-$ARCH"
echo "$SHA  $TMP" | sha256sum -c - >/dev/null 2>&1 || die "checksum mismatch - aborting"
install -m 0755 "$TMP" /usr/local/bin/coremon-agent

mkdir -p /etc/coremon /var/lib/coremon
chmod 700 /etc/coremon /var/lib/coremon

# Always (re)write the master address and keys: a repeated install command
# fixes a system whose master key changed. An existing registration is
# kept; if the master no longer knows it, the agent registers again with
# the token.
if [ "$ENROLLED" = 1 ]; then
  echo "coremon: already enrolled - updating the agent, master address and master keys (registration kept)"
fi
umask 077
cat > /etc/coremon/agent.json <<EOF
{
  "master_url": "$MASTER",
  "master_pins": ["$PIN", "$NEXT"],
  "token": "$TOKEN"
}
EOF

cat > /etc/systemd/system/coremon-agent.service <<'EOF'
[Unit]
Description=coremon agent
Wants=network-online.target
After=network-online.target

[Service]
ExecStart=/usr/local/bin/coremon-agent
Restart=on-failure
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload
systemctl enable coremon-agent.service >/dev/null 2>&1
systemctl restart coremon-agent.service
echo "coremon: agent installed and started."
if [ "$ENROLLED" = 0 ]; then
  echo "coremon: approve this system in the master UI (Settings > Systems): $MASTER"
fi
`))

// baseURL is the agent-facing URL: the Master URL setting (validated when
// saved), or else derived from the request. "" if the request's host is
// not a plain host name or IP address.
func (s *Server) baseURL(r *http.Request) string {
	s.st.mu.Lock()
	u := s.st.st.Settings.MasterURL
	s.st.mu.Unlock()
	if u != "" {
		return strings.TrimRight(u, "/")
	}
	return s.derivedURL(r)
}

// hostNameRe: DNS names. The host ends up in a shell script that runs as
// root, so nothing but letters, digits, dots and dashes is accepted.
var hostNameRe = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9.-]{0,252}[A-Za-z0-9])?$`)

// safeHost returns the host part of a Host header if it is a plain DNS name
// or IP address, else "".
func safeHost(hostport string) string {
	host := hostport
	if h, _, err := net.SplitHostPort(hostport); err == nil {
		host = h
	}
	host = strings.TrimSuffix(strings.TrimPrefix(host, "["), "]")
	if ip := net.ParseIP(host); ip != nil {
		return ip.String()
	}
	if hostNameRe.MatchString(host) {
		return host
	}
	return ""
}

// derivedURL guesses the agent-facing URL from the request: the host the
// browser used, with the agents' port. Agents never use the website-only
// port 443 or a reverse proxy, so the website port can change freely.
func (s *Server) derivedURL(r *http.Request) string {
	host := safeHost(r.Host)
	if host == "" {
		return ""
	}
	return "https://" + net.JoinHostPort(host, s.agentPort())
}

const badHostMsg = "the address this page was opened with is not a plain host name or IP address; set the Master URL under Settings > General"

func (s *Server) handleInstallScript(w http.ResponseWriter, r *http.Request) {
	base := s.baseURL(r)
	if base == "" {
		http.Error(w, badHostMsg, http.StatusBadRequest)
		return
	}
	latest := s.repo.coreLatest()
	keys := s.desiredPins() // during a rotation also the new key
	data := struct{ URL, Pin, Next, SHAAmd64, SHAArm64 string }{URL: base, Pin: keys[0], Next: keys[1]}
	if e := s.repo.find("core", latest, "linux", "amd64"); e != nil {
		data.SHAAmd64 = e.SHA256
	}
	if e := s.repo.find("core", latest, "linux", "arm64"); e != nil {
		data.SHAArm64 = e.SHA256
	}
	w.Header().Set("Content-Type", "text/x-shellscript; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_ = installTpl.Execute(w, data)
}

func (s *Server) installCommand(r *http.Request, token string) string {
	return "curl -fsSLk --pinnedpubkey 'sha256//" + s.currentPin() + "' " + s.baseURL(r) + "/install.sh | sh -s -- --token " + token
}
